const uint8_t *slab_glyph_s(char c)
{
    unsigned char u = (unsigned char)c;
    if (u == 0xB7) {
        return kMiddotS;
    }
    if (u < 32 || u > 127) {
        return &kFontS[0];
    }
    return &kFontS[(u - 32) * 12];
}

const uint8_t *slab_glyph_m(char c)
{
    unsigned char u = (unsigned char)c;
    if (u < 32 || u > 127) {
        return &kFontM[0];
    }
    return &kFontM[(u - 32) * 32];
}
